<template>
<v-card rounded="xl" flat border><v-card-title>沿岸候选点位</v-card-title><v-card-text><div class="actions mb-3"><v-chip color="error">红色：已确认污染</v-chip><v-chip color="warning">黄色：待确认</v-chip><v-chip color="success">绿色：已确认无污染</v-chip></div><p class="caption mb-3">悬停显示地名，点击点位查看详情和修改核查状态。测试点不代表实际排放设施。</p><div class="point-layout"><div ref="mapEl" class="region-map"></div><aside class="point-panel"><template v-if="chosen"><h3>{{chosen.name}}</h3><v-chip class="my-3" :color="color(chosen)">{{label(chosen)}}</v-chip><p v-if="chosen.metadata?.is_test" class="caption mb-3">测试点 · 状态仅用于测试</p><p class="caption mb-3">{{chosen.longitude.toFixed(5)}}°E，{{chosen.latitude.toFixed(5)}}°N</p><v-select v-model="state" label="核查状态" :items="states" variant="outlined"/><v-textarea v-model="basis" label="核查依据 / 备注" rows="3" variant="outlined"/><v-btn color="primary" :loading="saving" @click="save">保存点位状态</v-btn><p class="caption mt-3">{{chosen.evidence}}</p><a v-if="chosen.metadata?.source_url" :href="chosen.metadata.source_url" target="_blank" rel="noopener">查看坐标出处</a><v-alert v-if="message" class="mt-3" :type="failed?'error':'success'">{{message}}</v-alert></template><p v-else class="empty">点击地图上的圆点<br>这里会显示地名、状态和核查依据</p></aside></div><v-checkbox v-if="activeRecord?.observation_area" v-model="showArea" label="显示当前记录的观测范围" hide-details/><p v-if="flow?.available" class="caption mt-3">{{flow.provider}} · {{new Date(flow.start*1000).toLocaleString()}} 至 {{new Date(flow.end*1000).toLocaleString()}}</p></v-card-text></v-card>
</template>
<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue'
import L from 'leaflet'
const props=defineProps({candidates:{type:Array,default:()=>[]},records:{type:Array,default:()=>[]},flow:Object,traceResult:Object,activeRecord:Object})
const emit=defineEmits(['updated']);const mapEl=ref(null),chosen=ref(null),state=ref('SUSPECTED'),basis=ref(''),saving=ref(false),message=ref(''),failed=ref(false),showArea=ref(false)
const states=[{title:'待确认',value:'SUSPECTED'},{title:'已确认污染',value:'CONFIRMED_POLLUTION'},{title:'已确认无污染',value:'CLEARED'}]
let map,layers
function color(s){return s.metadata?.status==='CONFIRMED_POLLUTION'?'#d93025':s.metadata?.status==='CLEARED'?'#188038':'#f9ab00'}
function label(s){return states.find(x=>x.value===(s.metadata?.status||'SUSPECTED'))?.title||'待确认'}
function choose(s){chosen.value=s;state.value=s.metadata?.status||'SUSPECTED';basis.value=s.metadata?.status_basis||'';message.value=''}
async function save(){saving.value=true;message.value='';try{const r=await fetch('/api/candidate-sources/'+chosen.value.id+'/status',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:state.value,evidence:basis.value})});if(!r.ok){const j=await r.json();throw new Error(j.detail||'保存失败')}failed.value=false;message.value='状态已保存';emit('updated')}catch(e){failed.value=true;message.value=e.message}finally{saving.value=false}}
function draw(){if(!map)return;layers.clearLayers();for(const s of props.candidates){const name=document.createElement('span');name.textContent=s.name;L.circleMarker([s.latitude,s.longitude],{radius:8,color:color(s),fillColor:color(s),fillOpacity:.85,weight:2}).bindTooltip(name,{direction:'top'}).on('click',()=>choose(s)).addTo(layers)}const a=props.activeRecord?.observation_area;if(showArea.value&&a)L.rectangle([[a.south,a.west],[a.north,a.east]],{color:'#1a73e8',weight:1,fillOpacity:.03,interactive:false}).addTo(layers);for(const tr of props.traceResult?.result?.tracks||[])if(tr.length>1)L.polyline(tr.map(p=>[p[1],p[0]]),{color:'#607d8b',weight:1,opacity:.4,interactive:false}).addTo(layers);if(chosen.value){const fresh=props.candidates.find(s=>s.id===chosen.value.id);if(fresh)chosen.value=fresh}}
onMounted(()=>{map=L.map(mapEl.value);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);layers=L.layerGroup().addTo(map);map.fitBounds([[30.7,121.6],[31.4,122.05]]);draw()})
watch(()=>[props.candidates,props.traceResult,showArea.value,props.activeRecord],draw,{deep:true});onBeforeUnmount(()=>map?.remove())
</script>
<style scoped>.point-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:20px}.region-map{position:relative;overflow:hidden;isolation:isolate;height:560px;border-radius:14px;z-index:0}.point-panel{padding:16px;border:1px solid #e4e7eb;border-radius:14px}@media(max-width:1000px){.point-layout{grid-template-columns:1fr}.region-map{height:420px}}</style>
